 K(110,0,.6)+''.join(f'<circle cx="{110+80*math.cos(k*0.785)}" cy="{84+60*math.sin(k*0.785)}" r="9" fill="{["#ffd60a","#555","#e05a8a","#2a7a4a","#c0703a","#9fd3f0","#fff","#ff8c1a"][k]}" stroke="#111"/>' for k in range(8)),'Krishna at the centre of a ring of beings of many kinds',
