 [('kena upāyena','<b>by what means</b>'),('laghunā','<b>easy</b>, short'),('nāma-sahasrakam','<b>the thousand names</b>'),('paṭhyate','<b>is recited</b>'),('paṇḍitaiḥ','<b>by the wise</b>'),('śrotum icchāmi','<b>I wish to hear</b>')],
