 VIS(110,0,.6)+''.join(f'<ellipse cx="{20+20*k}" cy="{20+(k%2)*6}" rx="5" ry="3" fill="#fff" stroke="#111"/>' for k in range(10))+''.join(f'<path d="M{20+20*k} 150 v-10" stroke="#3b6fd0" stroke-width="4"/>' for k in range(10))+lab(110,156,'SAHASRA',9),'The cosmic figure with many eyes above and many feet below',
 'Brahmā said: Salutations to the Endless One of a thousand forms, with a thousand feet, eyes, heads, thighs and arms; to the eternal Person of a thousand names, who upholds a thousand crores of ages: salutations.',
